  /而是/g,
  /要.*?而不是/g,
  /——|—|–/g,
  /很有意思/g,
  /下面/g,
  /关键是/g,
  /值得/g,
  /多问一句/g,
  /其实/g,
  /可以说/g,
  /总的来说/g,
  /综上所述/g,
  /\*\*.*?\*\*/g
];

